g('iv5:1','무위험자산(rf)에서 위험자산 곡선에 접하는 직선이 자본시장선. 기울기가 가장 큰 = 샤프비율 최대.',()=>{const f=E=>Math.sqrt(100+6*(E-6)**2),rf=2;let best=0,bE=6;for(let E=6;E<14;E+=.01){const s=(E-rf)/f(E);if(s>best){best=s;bE=E}}const bs_=f(bE);return plot({x:[0,30],y:[0,16],xl:'위험 σ',yl:'기대수익률',xt:[0,10,20,30],yt:[4,8,12],s:[{p:par(E=>[f(E),E],6,14.5),c:'m',l:'위험자산 조합',lp:[29,14.5],la:'end',ldy:16},{f:x=>rf+best*x,c:'a',l:'자본시장선(CML)',lp:[12,rf+best*12],la:'end',ldx:-6,ldy:-8}],pt:[{x:0,y:rf,l:'rf',dx:6,dy:-6},{x:bs_,y:bE,l:'시장 포트폴리오 M',c:'r',dy:14}]})});
