g('fs6:0','PER = 배당성향 ÷ (r − g). 요구수익률 9%, 배당성향 50%일 때 성장률별 적정 PER.',()=>plot({x:[0,7],y:[0,28],xl:'성장률 g(%)',yl:'적정 PER(배)',xt:[0,1,2,3,4,5,6,7],yt:[5,10,15,20,25],s:[{f:g=>.5/(.09-g/100),c:'a'}],pt:[{x:0,y:5.6,l:'5.6배'},{x:4,y:10,l:'10배',a:'end',dx:-6},{x:7,y:25,l:'25배',a:'end',dx:-6}]}));
