g('fs7:0','DCF의 뼈대: 미래 현금을 오늘 가치로 바꿔 더한 뒤, 주주 몫만 남겨요.',()=>flow({n:['FCF 추정 (5~10년)','WACC로 할인 → 현재가치 합','+ 터미널가치의 현재가치','= 기업가치(EV)','− 순차입금 = 주주가치',{t:'÷ 주식 수 = 주당 가치',b:1,c:'g'}]}));
g('fs7:1','FCF 100이 5년간 8% 성장, WACC 9%, 영구성장 2.5%. 가치의 대부분이 터미널가치예요.',()=>{let pv=0,f=100;for(let t=1;t<=5;t++){f*=1.08;pv+=f/1.09**t}const tv=f*1.025/(.09-.025)/1.09**5,tot=pv+tv;return hstack({s:[[Math.round(pv/tot*100),'t','예측기간 5년 FCF'],[Math.round(tv/tot*100),'a','터미널가치']],u:'%'})});
g('fs7:2','FCF 100의 가치 = 100 ÷ (WACC − g). 가정을 1%p만 바꿔도 가치가 40~70% 달라져요.',()=>{const base=100/.06;const cell=(w,g)=>{const v=100/((w-g)/100),d=v/base-1;return{t:nf(v),c:Math.abs(d)<.01?'k':d>0?'g':'r'}};return table({hd:['WACC \\ g','1%','2%','3%'],ctr:1,cw:[.28,.24,.24,.24],r:[7,8,9,10].map(w=>[w+'%',...[1,2,3].map(g=>cell(w,g))])})});
g('fs7:3','여러 방법의 가치 범위를 겹쳐 보는 "풋볼필드". 현재가가 범위 아래쪽이면 안전마진이 있어요.',football);
